// Author: MiYu. Real ancient orders exercise counted placement, movement, source weapons and defense, production and shared mine release.
#include "session.h"
#include "setup.h"
#include "scene_assets.h"
#include "model.h"
#include <cctype>
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_roots_tests <data-root> <fixture> [models]");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto real=[&](float value){return vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(value)));};auto point=[&](float x,float y){return WorldPoint{jass::Real::fromBits(std::bit_cast<std::uint32_t>(x)),jass::Real::fromBits(std::bit_cast<std::uint32_t>(y))};};auto type=[&](const char* value){return vm.integer(int(ObjectData::code(value)));};auto player=call("Player",{vm.integer(0)});auto spawn=[&](const char* code,float x,float y,unsigned owner=0){return call("CreateUnit",{call("Player",{vm.integer(owner)}),type(code),real(x),real(y),real(270)});};auto immediate=[&](jass::Value u,const char* name){return call("IssueImmediateOrder",{u,vm.string(name)}).bits!=0;};for(unsigned key:{1u,2u,4u,6u})call("SetPlayerState",{player,vm.handle("playerstate",key),vm.integer(key<4?100000:1000)});
        if(argc==4){if(std::wstring_view(argv[3])!=L"models")throw std::runtime_error("Unknown root test mode");SceneAssets assets(session.world()->resources());Log log(std::filesystem::path(argv[2]).parent_path()/L"model-import.log");auto hasAlternate=[](Model& model){auto name=model.sequenceName();for(auto& c:name)c=char(std::tolower(static_cast<unsigned char>(c)));return name.find("alternate")!=std::string::npos;};for(auto member:{"buildings/nightelf/TreeofLife/TreeofLife.mdx","buildings/nightelf/AncientOfWar/AncientOfWar.mdx","buildings/nightelf/AncientProtector/AncientProtector.mdx"}){auto& model=assets.model(member,log);require(model.sequence("Stand Alternate") && hasAlternate(model),"Rooted source model did not select its alternate standing pose");require(model.sequence("Walk") && !hasAlternate(model),"Uprooted source model did not select its normal walk");require(model.sequence("Morph") && !hasAlternate(model) && model.sequence("Morph Alternate") && hasAlternate(model),"Source root transitions did not select their direction");require(model.sequence("Spell Eat Tree"),"Source EatTree spelling variant did not select its real animation");}auto& statue=assets.model("units/undead/ObsidianStatue/ObsidianStatue.mdx",log);require(statue.sequence("Stand") && !hasAlternate(statue) && statue.sequence("Stand Alternate") && hasAlternate(statue),"Normal statue and Destroyer standing animations were not isolated");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS source_ancient_and_statue_animation_properties GPU=pending\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}
        auto ancient=spawn("eaom",0,0);auto a=session.units().at(ancient.bits);call("SetUnitAcquireRange",{ancient,real(0)});call("SetUnitUserData",{ancient,vm.integer(123)});require(a->roots && !a->roots->uprooted && a->animationProperties=="Alternate" && !a->footprint.empty() && !session.moveUnit(ancient.bits,point(64,0)),"Source rooted ancient did not initialize its real anchored state");require(immediate(ancient,"unroot"),"Unroot source order rejected");session.advance(4);require(a->mobileBuilding() && a->footprint.empty() && a->animationProperties.empty() && !a->rootTransition,"Unroot did not release footprint, transition and animation state");require(!session.train(ancient.bits,ObjectData::code("earc")),"Uprooted ancient accepted training");auto buttons=session.abilityCommands(ancient.bits,0);auto rootButton=std::find_if(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("Aro1");});require(rootButton!=buttons.end() && rootButton->enabled && rootButton->icon.find("BTNRoot")!=std::string::npos && session.spellTargeting(*a,session.spellInfo(ObjectData::code("Aro1"),1))==SpellTargeting::Point,"Root source button or point targeting did not switch");auto& terrain=session.world()->data().terrain;std::optional<WorldPoint> site;std::string reason;for(unsigned y=8;y+8<(terrain.height-1)*4 && !site;y+=4)for(unsigned x=8;x+8<(terrain.width-1)*4 && !site;x+=4)site=session.rootSite(ancient.bits,point(terrain.origin[0]+x*32,terrain.origin[1]+y*32),reason);require(site.has_value(),"No legal root site in source terrain");float x=number(site->x),y=number(site->y);call("SetUnitPosition",{ancient,real(x),real(y)});require(session.moveUnit(ancient.bits,point(x+64,y)),"Uprooted movement order rejected");session.advance(2);require(std::hypot(number(a->x)-x-64,number(a->y)-y)<1,"Uprooted ancient did not consume its source movement speed");call("SetUnitPosition",{ancient,real(x),real(y)});auto blocker=spawn("hhou",x,y);require(!session.rootSite(ancient.bits,*site,reason),"Root placement ignored a real occupied building footprint");call("RemoveUnit",{blocker});require(call("IssuePointOrder",{ancient,vm.string("root"),real(x),real(y)}).bits!=0,"Root point order rejected");session.advance(1);require(a->rootTransition && !a->footprint.empty() && !session.moveUnit(ancient.bits,point(x+64,y)),"Root transition did not reserve footprint and lock movement");call("UnitRemoveAbility",{ancient,type("Aro1")});require(!a->rootTransition && a->mobileBuilding() && a->footprint.empty(),"Cancelled rooting retained reserved occupancy");require(call("UnitAddAbility",{ancient,type("Aro1")}).bits!=0,"Root ability could not be restored");require(call("IssuePointOrder",{ancient,vm.string("root"),real(x),real(y)}).bits!=0,"Repeated root point order rejected");session.advance(4);require(a->stationaryBuilding() && !a->footprint.empty() && a->animationProperties=="Alternate" && a->type==ObjectData::code("eaom") && a->userData==123,"Root completion did not preserve identity and restore actual building state");require(session.train(ancient.bits,ObjectData::code("earc")) && !immediate(ancient,"unroot"),"Rooted training or busy unroot restriction missing");require(session.cancelProduction(ancient.bits),"Training cleanup failed");std::cout<<"PASS ancient_root_move_placement_cancel_identity_ui_and_training\n";
        auto protector=spawn("etrp",x+1024,y);auto p=session.units().at(protector.bits);require(call("IsUnitType",{protector,vm.handle("unittype",8)}).bits && !call("IsUnitType",{protector,vm.handle("unittype",7)}).bits,"Rooted protector did not select its source ranged weapon");float before=number(p->life);require(session.damageUnit(ancient.bits,protector.bits,100,1,4),"Rooted armor damage rejected");float rootedDamage=before-number(p->life);require(immediate(protector,"unroot"),"Protector unroot rejected");session.advance(4);require(call("IsUnitType",{protector,vm.handle("unittype",7)}).bits && !call("IsUnitType",{protector,vm.handle("unittype",8)}).bits,"Uprooted protector did not switch to source melee weapon");before=number(p->life);require(session.damageUnit(ancient.bits,protector.bits,100,1,4) && before-number(p->life)>rootedDamage,"Uprooted defense type did not replace fortified armor classification");std::cout<<"PASS protector_source_weapon_switch_and_uprooted_defense\n";
        auto tree=spawn("etol",x+2048,y),mine=spawn("ngol",x+2048,y+512,15);auto t=session.units().at(tree.bits);require(session.entangleMine(tree.bits,mine.bits,true),"Source entangled mine setup rejected");auto cover=t->mineChild;require(cover!=0,"Entangled mine did not link the tree");call("SetResourceAmount",{vm.handle("unit",cover),vm.integer(1234)});require(immediate(tree,"unroot"),"Tree with entangled mine could not unroot");session.advance(4);require(t->mobileBuilding() && !t->mineChild && !session.units().at(mine.bits)->mineCover && !session.units().at(mine.bits)->hidden() && session.remainingResources(mine.bits)==1234 && !session.entangleMine(tree.bits,mine.bits,true),"Unroot did not release the mine or prevent mobile entangling");std::cout<<"PASS unroot_releases_entangled_mine_and_preserves_gold\n";
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=3 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
